function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }
const hdr = (($('GET header').first().json.values || [[]])[0] || []).map(s);
const cP = hdr.indexOf('pause'), cN = hdr.indexOf('notes');
if (cP < 0 || cN < 0) { throw new Error('ABORT: pause/notes column missing: ' + JSON.stringify(hdr)); }
function colLetter(i) { let n = i + 1, out = ''; while (n > 0) { const m = (n - 1) % 26; out = String.fromCharCode(65 + m) + out; n = Math.floor((n - 1) / 26); } return out; }
const LP = colLetter(cP), LN = colLetter(cN);
const invRaw = $('Read INVESTORS').all().map(function (i) { return i.json; });
const pipe = $input.all().map(function (i) { return i.json; });
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }

// an investor counts as 'stage missing' only if EVERY INVESTORS row under that name has a blank stage
const hasStage = {}, names = {};
for (const r of invRaw) { const n = s(r.investor); if (!n) { continue; } const k = nz(n); names[k] = n;
  if (s(r.stage) !== '') { hasStage[k] = true; } else if (hasStage[k] === undefined) { hasStage[k] = false; } }
const missing = {}; for (const k of Object.keys(hasStage)) { if (!hasStage[k]) { missing[k] = names[k]; } }

const holds = []; const perInv = {}; const sentPerInv = {};
for (const k of Object.keys(missing)) { perInv[k] = 0; sentPerInv[k] = 0; }
for (const p of pipe) {
  const k = nz(p.investor); if (!missing[k]) { continue; }
  if (s(p.deal_shared).toLowerCase() === 'yes') { sentPerInv[k]++; continue; }   // sent rows untouched
  if (s(p.pause).toLowerCase() === 'yes') { continue; }                           // already on hold
  if (!p.row_number) { throw new Error('ABORT: row without row_number'); }
  const note = s(p.notes);
  holds.push({ rn: p.row_number, deal: s(p.deal_id), st: s(p.startup), inv: s(p.investor),
    note: (note ? note + ' | ' : '') + 'ON HOLD 2026-09-10 - investor stage missing in INVESTORS' });
  perInv[k]++;
}
if (holds.length > 900) { throw new Error('ABORT: ' + holds.length + ' holds exceeds guard of 900'); }
if (!holds.length) { throw new Error('NOTHING TO DO: no queued deals for stage-missing investors'); }
const data = [];
for (const h of holds) {
  data.push({ range: 'PIPELINE!' + LP + h.rn, values: [['Yes']] });
  data.push({ range: 'PIPELINE!' + LN + h.rn, values: [[h.note]] });
}
const invList = Object.keys(missing).map(function (k) { return [missing[k], perInv[k], sentPerInv[k]]; })
  .sort(function (a, b) { return b[1] - a[1] || a[0].localeCompare(b[0]); });
return [{ json: { pause_col: LP, notes_col: LN, investors_stage_missing: invList.length, deals_put_on_hold: holds.length,
  investor_cols: ['investor', 'queued_deals_held', 'already_sent_untouched'], investors: invList,
  held: holds.map(function (h) { return [h.rn, h.deal, h.st, h.inv]; }), data: data } }];
